<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<link rel="icon" href="data:,">
<title>Solmar Heist — an open-world crime game</title>
<style>
  :root {
    --ink: #f2ede0; --muted: #9aa3b2; --amber: #ffb02e; --red: #e5484d;
    --green: #58c96b; --blue: #4fa8e8; --panel: rgba(12, 16, 24, 0.78);
    --font-ui: system-ui, -apple-system, "Segoe UI", sans-serif;
    --font-readout: ui-monospace, "SF Mono", Menlo, monospace;
  }
  * { box-sizing: border-box; }
  html, body { margin: 0; height: 100%; overflow: hidden; background: #0d1420; color: var(--ink); font-family: var(--font-ui); }
  #game { position: fixed; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }
  #status { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  .hud { position: fixed; z-index: 5; pointer-events: none; user-select: none; }
  #hud-top-left { top: 14px; left: 14px; display: flex; flex-direction: column; gap: 8px; }
  .chip { background: var(--panel); border: 1px solid rgba(255,255,255,0.12); border-radius: 8px; padding: 8px 12px; font-family: var(--font-readout); }
  #cash { font-size: 22px; color: var(--green); font-weight: 700; }
  #health-wrap { width: 200px; }
  #health-label { font-size: 12px; color: var(--muted); display: flex; justify-content: space-between; }
