      pole.position.set(cx + 6.5, 3.5, cz + 6.5);
      scene.add(pole);
      const lamp = new THREE.Mesh(new THREE.SphereGeometry(0.32, 8, 6), lampMat);
      lamp.position.set(cx + 6.5, 7.1, cz + 6.5);
